def max_profit_brute(prices):
    n = len(prices)

    def helper(day, holding):
        if day == n:
            return 0
        skip = helper(day + 1, holding)                      # do nothing today
        if holding:
            sell = prices[day] + helper(day + 1, False)         # sell today
            return max(skip, sell)
        else:
            buy = -prices[day] + helper(day + 1, True)           # buy today
            return max(skip, buy)

    return helper(0, False)

