public class Main {
    static int maxProfit(int[] prices) {
        int profit = 0;
        for (int i = 1; i < prices.length; i++) {
            if (prices[i] > prices[i - 1]) {                    // capture this day's increase
                profit += prices[i] - prices[i - 1];
            }
        }
        return profit;
    }
}

